text:
inline-size: 100%;
max-inline-size: var(--hub-width);
text-align: start;
margin-inline: 0;

&.flex-direction-row {
  flex-direction: row;
}

&.auto-config-body {
  max-inline-size: 750px;
}

&.manual-form-body {
  gap: 20px;

  & .form-row {
    display: grid;
    grid-template-columns: 115px 1fr;
    gap: 10px;

    .stacked & {
      grid-template-columns: 1fr;
    }

    &.responsive-row {
      grid-template-columns: auto 1fr;

      .stacked & {
        grid-template-columns: 1fr;
      }
    }

    & .expanded {
      flex: 1;
    }
  }
}

&.manual-config-body {
  gap: calc(8 * var(--space-step));
  padding-block: calc(3 * var(--space-step));
}

&.hub-form-grid {
  gap: 18px;
  --hub-width: 530px;
  display: grid;
  grid-template: repeat(3, auto 1fr) auto / repeat(4, 1fr);

  &.advanced {
    grid-template-rows: repeat(4, auto 1fr);
  }

  .stacked & {
    grid-template: repeat(6, auto 1fr) auto / repeat(2, 1fr);

    &.advanced {
      grid-template-rows: repeat(11, auto 1fr);
    }
  }

  & .input-cell {
    display: grid;
    grid-template-rows: subgrid;
    grid-row: span 2;
    gap: 3px;

    &.select-row {
      --account-hub-select-margin: 3px;
      grid-template-rows: none;
    }
